        /// <summary>
        /// Updating avatar for user.
        /// </summary>
        /// <param name="custId">Customer identify.</param>
        /// <param name="isDefaultAvatar">Use default avatar or not.</param>
        /// <param name="isFromURL">Upload avatar from URL or not.</param>
        /// <param name="urlAvatar">Link of URL avatar.</param>
        /// <param name="file">File uploading.</param>
        /// <returns>Return to success or not.</returns>
        [HttpPost]
        public ActionResult UpdatingProfilePicture(int custId, bool isDefaultAvatar, bool isFromURL, string urlAvatar, HttpPostedFileBase file)
        {
            Result result = new Result();
            try
            {
                if (SessionExtension.IsSubAcc || SessionExtension.IsInternal)
                {
                    return new JsonResult()
                    {
                        ContentType = "text/html",
                        Data = new Result
                        {
                            ErrorCode = -16,
                            ErrorMessage = ResourceExtension.GetResource("ProfilePicture", "NotAuthorized")
                        }
                    };
                }

                if (string.IsNullOrEmpty(urlAvatar) && file == null && !isDefaultAvatar)
                {
                    return new JsonResult()
                    {
                        ContentType = "text/html",
                        Data = new Result
                        {
                            ErrorCode = -16,
                            ErrorMessage = ResourceExtension.GetResource("ProfilePicture", "FailByUnknownreason")
                        }
                    };
                }

                AvatarUpdatingCriteria avatarUpdatingCriteria = new AvatarUpdatingCriteria
                {
                    CustID = custId,
                    IsDefaultAvatar = isDefaultAvatar,
                    IP = CustomerIp()
                };

                if (!isDefaultAvatar)
                {
                    if (isFromURL)
                    {
                        avatarUpdatingCriteria.Avatar = FileUpload.SaveFileFromURL(urlAvatar, ref result);
                    }
                    else
                    {
                        avatarUpdatingCriteria.Avatar = FileUpload.SaveFileFromComputer(file, ref result);
                    }

                    if (!result.ErrorCode.Equals(0))
                    {
                        return new JsonResult() { ContentType = "text/html", Data = result };
                    }
                }

                result = _profilePictureService.UpdatingAvatar(avatarUpdatingCriteria);
            }
            catch (Exception ex)
            {
                LoggingHandler.Log(ex);
            }

            return new JsonResult() { ContentType = "text/html", Data = result };
        }

        /// <summary>
