        public ActionResult CustomerProfile()
        {
            ProfilePicture profile = new ProfilePicture();

            ViewBag.CountNicknameTooltip = CountNickNameToolTip;

            if (CountNickNameToolTip < 4)
            {
                CountNickNameToolTip++;
            }

            profile = _profilePictureService.SelectingAvatar(_userId);
            ViewBag.IsDefaultAvatar = SessionExtension.IsDefaultAvatar;
            ViewBag.BinaryAvatar = GenerateImage(_userId);
            if (profile.AvatarBinary == null)
            {
