        /// <param name="custId">Customer identify.</param>
        /// <returns>String avatar.</returns>
        public string GenerateImage(int custId)
        {
            ProfilePicture profile = new ProfilePicture();
            try
            {
                byte[] binaryAvatar = SessionExtension.BinaryAvatar;
                if (binaryAvatar != null)
                {
                    return "data:image/jpeg;base64," + Convert.ToBase64String(binaryAvatar);
                }
                else
                {
                    profile = _profilePictureService.SelectingAvatar(custId);
                }
            }
            catch (Exception ex)
            {
                LoggingHandler.Log(ex);
            }

            return "data:image/jpeg;base64," + Convert.ToBase64String(profile.AvatarBinary);
        }

